/** Atomic weights in g/mol (inline table per spec). */
export const ATOMIC_WEIGHTS = {
  H: 1.008,
  C: 12.011,
  N: 14.007,
  O: 15.999,
  Na: 22.99,
  S: 32.06,
  Fe: 55.845,
  Cu: 63.546,
} as const;

export type ElementSymbol = keyof typeof ATOMIC_WEIGHTS;

/**
 * Tokenizer for chemical formulas.
 *
 * Grammar handled by the parser (see parser.ts):
 *   formula := group ('.' group)*          -- dot-hydrate notation
 *   group   := unit integer?               -- trailing multiplier applies to the unit
 *   unit    := element | '(' formula ')'   -- nested parentheses
 *   element := [A-Z][a-z]?                 -- e.g. 'H', 'Fe', 'Na'
 *   integer := [0-9]+                      -- e.g. '2', '12'
 */

export type TokenType = "element" | "integer" | "lparen" | "rparen" | "dot";

export interface Token {
  type: TokenType;
  /** Raw text of the token. */
  value: string;
  /** 1-based position in the input string. */
  pos: number;
}

const ELEMENT_START = /[A-Z]/;
const ELEMENT_CONTINUE = /[a-z]/;
const DIGIT = /[0-9]/;

export class FormulaSyntaxError extends Error {
  readonly pos: number;

  constructor(message: string, pos: number) {
    super(`${message} at position ${pos}`);
    this.name = "FormulaSyntaxError";
    this.pos = pos;
  }
}

/** Convert a formula string into a flat token stream. */
export function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (ch === "(") {
      tokens.push({ type: "lparen", value: ch, pos: i });
      i += 1;
      continue;
    }

    if (ch === ")") {
      tokens.push({ type: "rparen", value: ch, pos: i });
      i += 1;
      continue;
    }

    if (ch === "." || ch === "·") {
      // Accept both ASCII dot and middle-dot as hydrate separators.
      tokens.push({ type: "dot", value: ".", pos: i });
      i += 1;
      continue;
    }

    if (DIGIT.test(ch)) {
      const start = i;
      while (i < input.length && DIGIT.test(input[i])) i += 1;
      tokens.push({ type: "integer", value: input.slice(start, i), pos: start });
      continue;
    }

    if (ELEMENT_START.test(ch)) {
      const start = i;
      i += 1;
      if (i < input.length && ELEMENT_CONTINUE.test(input[i])) {
        // Only consume the lowercase letter if it forms a known two-letter
        // symbol continuation; otherwise it is a syntax error caught by the
        // parser (e.g. 'Xx' -> unknown element).
        i += 1;
      }
      tokens.push({ type: "element", value: input.slice(start, i), pos: start });
      continue;
    }

    throw new FormulaSyntaxError(`Unexpected character ${JSON.stringify(ch)}`, i);
  }

  return tokens;
}

