import { ATOMIC_WEIGHTS, type ElementSymbol } from "./weights.js";
import {
  FormulaSyntaxError,
  tokenize,
  type Token,
  type TokenType,
} from "./tokenizer.js";

/**
 * Recursive-descent parser for chemical formulas.
 *
 * Grammar:
 *   formula := group ('.' group)*          -- dot-hydrate notation
 *   group   := unit integer?               -- optional trailing multiplier
 *   unit    := element | '(' formula ')'   -- nested parentheses
 */

const KNOWN = new Set(Object.keys(ATOMIC_WEIGHTS));

class Parser {
  private tokens: Token[];
  private index = 0;

  constructor(input: string) {
    this.tokens = tokenize(input);
  }

  /** Parse the whole input; returns element counts (symbol -> count). */
  parse(): Map<ElementSymbol, number> {
    const totals = this.parseFormula();

    if (this.peek()) {
      throw new FormulaSyntaxError(
        `Unexpected token '${this.peek()!.value}'`,
        this.peek()!.pos,
      );
    }

    if (totals.size === 0) {
      throw new FormulaSyntaxError("Empty formula", 1);
    }

    return totals;
  }

  private peek(): Token | undefined {
    return this.tokens[this.index];
  }

  private expect(type: TokenType): Token {
    const tok = this.peek();
    if (!tok || tok.type !== type) {
      throw new FormulaSyntaxError(
        `Expected ${type}, got ${tok ? `'${tok.value}'` : "end of input"}`,
        tok ? tok.pos : this.lastPos(),
      );
    }
    this.index += 1;
    return tok;
  }

  private lastPos(): number {
    const last = this.tokens[this.tokens.length - 1];
    return last ? last.pos + last.value.length : 1;
  }

  /** formula := group ('.' group)* */
  private parseFormula(): Map<ElementSymbol, number> {
    const first = this.peek();
    if (!first) {
      throw new FormulaSyntaxError("Empty formula", 1);
    }

    let totals = this.parseGroup();

    while (this.peek()?.type === "dot") {
      this.index += 1; // consume '.'
      const next = this.parseGroup();
      for (const [sym, n] of next) {
        totals.set(sym, (totals.get(sym) ?? 0) + n);
      }
    }

    return totals;
  }

  /** group := unit integer? */
  private parseGroup(): Map<ElementSymbol, number> {
    const counts = this.parseUnit();

    const next = this.peek();
    if (next?.type === "integer") {
      this.index += 1;
      const mult = parseInt(next.value, 10);
      for (const [sym, n] of counts) counts.set(sym, n * mult);
    } else if (next?.type === "element" || next?.type === "lparen") {
      // e.g. 'CuSO' followed directly by another unit is fine — the loop in
      // parseFormula handles sequences via repeated groups at the top level.
    }

    return counts;
  }

  /** unit := element | '(' formula ')' */
  private parseUnit(): Map<ElementSymbol, number> {
    const tok = this.peek();

    if (!tok) {
      throw new FormulaSyntaxError(
        "Unexpected end of formula",
        this.lastPos(),
      );
    }

    if (tok.type === "element") {
      this.index += 1;
      if (!KNOWN.has(tok.value)) {
        throw new Error(
          `Unknown element '${tok.value}' at position ${tok.pos + 1}`,
        );
      }
      return new Map([[tok.value as ElementSymbol, 1]]);
    }

    if (tok.type === "lparen") {
      this.index += 1; // consume '('
      const inner = this.parseFormula();
      this.expect("rparen");
      return inner;
    }

    throw new FormulaSyntaxError(`Unexpected token '${tok.value}'`, tok.pos);
  }
}

/**
 * Compute the molar mass (g/mol) of a chemical formula.
 *
 * Supported syntax: element symbols with capital-first letter (H, Fe, Na),
 * integer multipliers after elements or closing parentheses, nested
 * parentheses, and dot-hydrate notation (e.g. CuSO4.5H2O).
 */
export function molarMass(formula: string): number {
  const trimmed = formula.trim();
  const counts = new Parser(trimmed).parse();

  let total = 0;
  for (const [sym, n] of counts) {
    total += ATOMIC_WEIGHTS[sym] * n;
  }
  return total;
}

