import { describe, expect, it } from "vitest";
import { molarMass } from "../src/index.js";

const WITHIN = 0.01;

describe("molarMass — known answers", () => {
  it.each([
    ["(NH4)2SO4", 132.134], // 2N + 8H + S + 4O
    ["Fe2(SO4)3", 399.858], // 2Fe + 3S + 12O
    ["C6H12O6", 180.156], // glucose
    ["CuSO4.5H2O", 249.677], // copper(II) sulfate pentahydrate
  ])("%s -> %f", (formula, expected) => {
    expect(molarMass(formula)).toBeCloseTo(expected, 2);
    expect(Math.abs(molarMass(formula) - expected)).toBeLessThanOrEqual(WITHIN);
  });
});

describe("molarMass — error cases", () => {
  it("throws on unknown element 'Xx2'", () => {
    expect(() => molarMass("Xx2")).toThrowError(/unknown element 'Xx'/i);
  });

  it("throws on unbalanced parentheses 'Ca(OH'", () => {
    expect(() => molarMass("Ca(OH")).toThrowError(/\)/i);
  });

  it("throws on empty formula ''", () => {
    expect(() => molarMass("")).toThrowError(/empty/i);
  });

  it("error messages are useful (contain position info where applicable)", () => {
    try {
      molarMass("Xx2");
      expect.unreachable();
    } catch (e) {
      expect((e as Error).message).toMatch(/Xx/);
    }
    try {
      molarMass("Ca(OH");
      expect.unreachable();
    } catch (e) {
      expect((e as Error).message).toMatch(/position|end of input|Expected/i);
    }
  });
});

describe("molarMass — sanity checks against hand-computed sums", () => {
  it("water and hydrate reuse O/H weights consistently", () => {
    // CuSO4.5H2O = Cu + S + (4+5)O + 10H
    const expected = 63.546 + 32.06 + 9 * 15.999 + 10 * 1.008;
    expect(molarMass("CuSO4.5H2O")).toBeCloseTo(expected, 6);
  });

  it("handles deeply nested parentheses", () => {
    // Ca(OH(H)2)2 is contrived; use a real nesting: Fe2(SO4)3 vs ((Fe)2((S)(O4))3)
    expect(molarMass("((Fe)2((S)(O4))3)")).toBe(molarMass("Fe2(SO4)3"));
  });

  it("multiplier of 1 is implicit", () => {
    expect(molarMass("NaCl".replace("Cl", ""))).toBe(22.99); // Na alone
  });
});

