/** group := integer? (unit integer?)+ -- consumes units until '.', ')', or end. */
private parseGroup(): Map<ElementSymbol, number> {
  const counts = new Map<ElementSymbol, number>();

  // Leading coefficient, e.g. the 5 in CuSO4.5H2O.
  let leading = 1;
  const first = this.peek();
  if (first?.type === "integer") {
    this.index += 1;
    leading = parseInt(first.value, 10);
  }

  let sawUnit = false;
  for (;;) {
    const next = this.peek();
    if (
      !next ||
      next.type === "dot" ||
      next.type === "rparen" ||
      next.type === "integer"
    ) {
      break;
    }

    for (const [sym, n] of this.parseUnitWithMultiplier()) {
      counts.set(sym, (counts.get(sym) ?? 0) + n);
    }
    sawUnit = true;
  }

  if (!sawUnit) {
    const tok = this.peek();
    throw new FormulaSyntaxError(
      tok ? `Unexpected token '${tok.value}'` : "Unexpected end of formula",
      tok ? tok.pos : this.lastPos(),
    );
  }

  if (leading !== 1) {
    for (const [sym, n] of counts) counts.set(sym, n * leading);
  }

  return counts;
}

