private static readonly TOKEN_NAMES: Record<TokenType, string> = {
  element: "an element symbol",
  integer: "a number",
  lparen: "'('",
  rparen: "')'",
  dot: ".",
};

private expect(type: TokenType): Token {
  const tok = this.peek();
  if (!tok || tok.type !== type) {
    const expected = Parser.TOKEN_NAMES[type];
    const got = tok ? `'${tok.value}'` : "end of input";
    const hint =
      type === "rparen" && !tok
        ? " (unbalanced parentheses: missing closing ')')"
        : "";
    throw new FormulaSyntaxError(
      `Expected ${expected}, got ${got}${hint}`,
      tok ? tok.pos : this.lastPos(),
    );
  }
  this.index += 1;
  return tok;
}

